INSERT INTO questions (source, year, subject, topic, enunciado, opcoes, gabarito, explicacao) VALUES
  ('exam', 2019, 'Economia', NULL, 'Q1 Item 1 (TPS 2019): Com base nas ideias apresentadas no texto, julgue (C ou E) os itens a seguir. | Nilo Peçanha deferiu o pedido de inscrição de Maria José de Castro Rebello Mendes no certame para a contratação de terceiro oficial da Secretaria de Estado, em razão da carência de pessoal por que vinha passando essa secretaria há mais de uma década.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2019, 'Economia', NULL, 'Q1 Item 2 (TPS 2019): Com base nas ideias apresentadas no texto, julgue (C ou E) os itens a seguir. | Em seu despacho, o chanceler demonstra apoio irrestrito à inscrição de Maria José de Castro Rebello Mendes, dados os dispositivos legais vigentes à época a esse respeito.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2019, 'Economia', NULL, 'Q1 Item 3 (TPS 2019): Com base nas ideias apresentadas no texto, julgue (C ou E) os itens a seguir. | As instruções aprovadas por meio do Decreto no 12.998, de 24 de abril de 1918, para os concursos para terceiros oficiais da Secretaria de Estado vêm sendo aperfeiçoadas desde então, mas muitas das instruções então aprovadas permanecem válidas até os dias de hoje.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2019, 'Economia', NULL, 'Q1 Item 4 (TPS 2019): Com base nas ideias apresentadas no texto, julgue (C ou E) os itens a seguir. | O requerimento de inscrição de Maria José de Castro Rebello Mendes, a despeito da polêmica causada, foi rapidamente deferido.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2019, 'Economia', NULL, 'Q2 Item 1 (TPS 2019): Com relação aos aspectos linguísticos do texto, julgue (C ou E) os itens a seguir. | Na linha 5, a omissão do pronome “se” junto da forma verbal “haver” promoveria incorreção e incoerência ao texto.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2019, 'Economia', NULL, 'Q2 Item 2 (TPS 2019): Com relação aos aspectos linguísticos do texto, julgue (C ou E) os itens a seguir. | A substituição do ponto e vírgula empregado após “Estado” (linha 11) por vírgula manteria a correção do texto.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2019, 'Economia', NULL, 'Q2 Item 3 (TPS 2019): Com relação aos aspectos linguísticos do texto, julgue (C ou E) os itens a seguir. | Na linha 37, é facultativo o emprego da preposição “a” em “no cargo a que aspira”.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2019, 'Economia', NULL, 'Q2 Item 4 (TPS 2019): Com relação aos aspectos linguísticos do texto, julgue (C ou E) os itens a seguir. | A forma nominal “adicionada” (linha 62) concorda em gênero e número com o nome “sentença” (linha 65) a que se refere. Espaço livre Língua Portuguesa Itens de 1 a 10 Texto 1 para responder às questões 1 e 2. Original datado de 1917, redigido conforme a grafia da época. 1 4 7 10 13 16 19 22 25 28 31 34 37 40 43 46 49 52 55 57 58 61 64 67 69 A história das mulheres na carreira diplomática tem início em um momento conturbado da cena internacional, com reflexos diretos no Brasil, em geral, e no Ministério das Relações Exteriores (MRE), em particular. O então chanceler era Nilo Peçanha, que devia haver-se, desde maio de 1917, com as sucessivas violações da soberania brasileira pelo império alemão, e, a partir de 26 de outubro daquele ano, com as obrigações decorrentes do engajamento brasileiro n', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2019, 'Economia', NULL, 'Q3 Item 1 (TPS 2019): Com base nas ideias do texto, julgue (C ou E) os itens a seguir. | As polêmicas e os debates acerca da língua portuguesa no decorrer do século 19 constituem-se em um debate político em torno da língua.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2019, 'Economia', NULL, 'Q3 Item 2 (TPS 2019): Com base nas ideias do texto, julgue (C ou E) os itens a seguir. | O texto critica a ausência de destaque, nas políticas linguísticas brasileiras, às influências das línguas africanas sobre a língua portuguesa.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2019, 'Economia', NULL, 'Q3 Item 3 (TPS 2019): Com base nas ideias do texto, julgue (C ou E) os itens a seguir. | Ao definir o “elemento linguístico negro”, João Ribeiro, em 1889, foi um precursor do debate acerca do papel das línguas africanas na formação do português do Brasil, revolucionando as ideias até então existentes a respeito do tema.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2019, 'Economia', NULL, 'Q3 Item 4 (TPS 2019): Com base nas ideias do texto, julgue (C ou E) os itens a seguir. | Para alguns estudiosos, a sonoridade africana está relacionada à ideia de cultura popular no Brasil.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2019, 'Economia', NULL, 'Q4 Item 1 (TPS 2019): No que se refere aos aspectos linguísticos do texto, julgue (C ou E) os itens a seguir. | Caso as orações coordenadas que aparecem entre as linhas 9 e 19 do texto (“reforça-se... brasileira”) fossem escritas em ordem sujeito-verbo, da forma sugerida a seguir, a correção e a coerência do texto seriam mantidas: a diferenciação entre fala e escrita é reforçada; os estudos lexicais e gramaticais são intensificados; narrativas sobre a história do português no Brasil são construídas; a documentação da língua em uso é defendida; o estatuto do português do Brasil – variedade, modalidade, dialeto ou língua – é debatido; a designação da língua falada no Brasil é debatida; elementos linguísticos são categorizados sob os rótulos de neologismos, estrangeirismos, brasileirismos, jargões; a possível origem crioula do português do Brasil é discutida; a autenticidade da língua do Brasil é polem', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2019, 'Economia', NULL, 'Q4 Item 2 (TPS 2019): No que se refere aos aspectos linguísticos do texto, julgue (C ou E) os itens a seguir. | A substituição de “Trata-se” (linha 20) por Esse fato trata-se manteria a correção e a coerência do texto.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2019, 'Economia', NULL, 'Q4 Item 3 (TPS 2019): No que se refere aos aspectos linguísticos do texto, julgue (C ou E) os itens a seguir. | Os termos “às”, em “às influências” (linhas 29 e 30) e “a”, em “a modificações” (linhas 34) introduzem complementos indiretos (respectivamente, nominal e verbal) e são intercambiáveis no texto, sendo correto, portanto, o emprego de a influências e às modificações.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2019, 'Economia', NULL, 'Q4 Item 4 (TPS 2019): No que se refere aos aspectos linguísticos do texto, julgue (C ou E) os itens a seguir. | A palavra “chave” (linha 49) foi empregada em sentido conotativo. Texto 3 para responder às questões 5 e 6. 1 4 7 10 13 16 19 22 25 28 31 34 37 40 43 46 49 52 55 58 61 A explosão de “Alegria, alegria” Alegria, Alegria, de Caetano Veloso, parece-me assumir, neste momento, uma importância semelhante a Desafinado, como expressão de uma tomada de posição crítica em face dos rumos da música popular brasileira. Ao fazer a defesa do “comportamento antimusical” do “desafinado”, Newton Mendonça & Tom Jobim (via João Gilberto) puseram naquela composição a teoria & prática do movimento: o desabafo sentimental do “desafinado” (muito bem afinado, por sinal) era, bem compreendido, um manifesto contra os preconceitos da harmonia clássica que bloqueavam a receptividade da suposta interlocutora (ou do próp', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2019, 'Economia', NULL, 'Q5 Item 1 (TPS 2019): Considerando os aspectos linguísticos e estilísticos do texto, julgue (C ou E) os itens a seguir. | Augusto de Campos, ao tratar de tema acerca da música popular brasileira, insere essa categoria artística em ambiência cultural ampla, utilizando-se, para tanto, de elementos textuais que compõem a linguagem literária, tais como a conotação e a subjetividade, em defesa do próprio ponto de vista.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2019, 'Economia', NULL, 'Q5 Item 2 (TPS 2019): Considerando os aspectos linguísticos e estilísticos do texto, julgue (C ou E) os itens a seguir. | O autor, por meio dos recursos da citação e da intertextualidade, utiliza-se de referências à cultura brasileira e à estrangeira como estratégia de argumentação ao defender a ideia de que a produção artística brasileira é autônoma e não sofre influências externas consistentes desde a Semana de Arte Moderna, quando adquiriu maturidade estética e, sobretudo, mais tarde, quando adquiriu universalidade com o Concretismo.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2019, 'Economia', NULL, 'Q5 Item 3 (TPS 2019): Considerando os aspectos linguísticos e estilísticos do texto, julgue (C ou E) os itens a seguir. | O emprego recorrente de parênteses no texto de Augusto de Campos reforça a presença predominante da função fática da linguagem, pois o autor interrompe a discussão acerca da canção de Caetano Veloso para, com informalidade própria dos textos literários, conversar com mais proximidade com o leitor.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2019, 'Economia', NULL, 'Q5 Item 4 (TPS 2019): Considerando os aspectos linguísticos e estilísticos do texto, julgue (C ou E) os itens a seguir. | Os termos “oswaldianamente” (linha 30), “deglutir” (linha 30) e “incorporar as conquistas” (linha 32), são alusivos ao Manifesto Antropofágico e ao Movimento Verde-Amarelo, cujas ideias de assimilação de diversas culturas sem construções mimetizadas percorrem todo o texto de Augusto de Campos.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2019, 'Economia', NULL, 'Q6 Item 1 (TPS 2019): Considerando os aspectos linguísticos e semânticos do texto, julgue (C ou E) os itens a seguir. | A palavra “como” (linha 64) exprime uma relação de conformidade em “Mas, como observou Décio Pignatari” (linhas 64 e 65), da mesma forma que em “como um adorno exterior” (linhas 77 e 78).', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2019, 'Economia', NULL, 'Q6 Item 2 (TPS 2019): Considerando os aspectos linguísticos e semânticos do texto, julgue (C ou E) os itens a seguir. | Nas linhas 40 e 41, “solipsistas” e “isolacionistas” aproximam-se semanticamente ao se referirem a preconceitos que aparentam ser expressão do nacionalismo, mas caracterizam-se, de acordo com o autor, por serem expressões solitárias e isoladas.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2019, 'Economia', NULL, 'Q6 Item 3 (TPS 2019): Considerando os aspectos linguísticos e semânticos do texto, julgue (C ou E) os itens a seguir. | Em “No estágio de desenvolvimento de nossa música, a discriminação proposta pelos “nacionalistas” só nos poderá fazer retornar à condição de fornecedores de “matéria-prima musical” (ritmos exóticos) para os países estrangeiros.” (linhas de 89 a 93), o acento indicativo de crase poderia ser suprimido, mantendo-se a correção gramatical e as principais informações do texto se acrescentássemos o pronome possessivo nossa antes do substantivo “condição”.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2019, 'Economia', NULL, 'Q6 Item 4 (TPS 2019): Considerando os aspectos linguísticos e semânticos do texto, julgue (C ou E) os itens a seguir. | Da leitura do texto infere-se que, no título, o emprego da palavra “explosão” e a alusão a “Alegria, Alegria” são ilustrativos e revelam apenas o sucesso da canção à época, pois a discussão do texto refere-se à música de Caetano e de João Gilberto, e não à cultura brasileira em geral. CONCURSO PÚBLICO TERCEIRO-SECRETÁRIO DA CARREIRA DE DIPLOMATA – TIPO “A” PÁGINA 5/15', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2019, 'Economia', NULL, 'Q7 Item 1 (TPS 2019): 1 4 7 10 13 16 19 22 25 28 29 Para fins deste Acordo, aplicar-se-ão as seguintes definições: [...] 14. “Áreas Restritas” – áreas dentro da jurisdição territorial da República Federativa do Brasil, designadas conjuntamente pelas Partes, às quais o Governo da República Federativa do Brasil somente permitirá acesso a pessoas autorizadas pelo Governo dos Estados Unidos da América, a fim de assegurar que, de maneira ininterrupta, possam monitorar, inspecionar, acessar e controlar o acesso a Veículos  | As “Áreas Controladas” terão maior dificuldade de acesso que as meras “Áreas Restritas”.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2019, 'Economia', NULL, 'Q7 Item 2 (TPS 2019): 1 4 7 10 13 16 19 22 25 28 29 Para fins deste Acordo, aplicar-se-ão as seguintes definições: [...] 14. “Áreas Restritas” – áreas dentro da jurisdição territorial da República Federativa do Brasil, designadas conjuntamente pelas Partes, às quais o Governo da República Federativa do Brasil somente permitirá acesso a pessoas autorizadas pelo Governo dos Estados Unidos da América, a fim de assegurar que, de maneira ininterrupta, possam monitorar, inspecionar, acessar e controlar o acesso a Veículos  | Na linha 10, a forma verbal “possam” refere-se às “Partes”.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2019, 'Economia', NULL, 'Q7 Item 3 (TPS 2019): 1 4 7 10 13 16 19 22 25 28 29 Para fins deste Acordo, aplicar-se-ão as seguintes definições: [...] 14. “Áreas Restritas” – áreas dentro da jurisdição territorial da República Federativa do Brasil, designadas conjuntamente pelas Partes, às quais o Governo da República Federativa do Brasil somente permitirá acesso a pessoas autorizadas pelo Governo dos Estados Unidos da América, a fim de assegurar que, de maneira ininterrupta, possam monitorar, inspecionar, acessar e controlar o acesso a Veículos  | Do texto, infere-se que o acesso permitido pelo Governo da República Federativa do Brasil a pessoas autorizadas pelo Governo da República Federativa do Brasil, pelo Governo dos Estados Unidos da América ou por governos de outros países envolvidos em Atividades de Lançamento não necessariamente implica autorização para monitorar, inspecionar, acessar, acompanhar e controlar o acesso a Veículos de Lançamento e Espaçonaves dos Estados Unidos da América, Equipamentos Afins e', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2019, 'Economia', NULL, 'Q7 Item 4 (TPS 2019): 1 4 7 10 13 16 19 22 25 28 29 Para fins deste Acordo, aplicar-se-ão as seguintes definições: [...] 14. “Áreas Restritas” – áreas dentro da jurisdição territorial da República Federativa do Brasil, designadas conjuntamente pelas Partes, às quais o Governo da República Federativa do Brasil somente permitirá acesso a pessoas autorizadas pelo Governo dos Estados Unidos da América, a fim de assegurar que, de maneira ininterrupta, possam monitorar, inspecionar, acessar e controlar o acesso a Veículos  | De conformidade com o disposto no texto, um governo estrangeiro envolvido em Atividades de Lançamento, não norte-americano, pode autorizar técnico de qualquer nacionalidade a ingressar na “Área Controlada”, dentro da jurisdição territorial do Brasil. Espaço livre Texto 4 para responder às questões 8 e 9. 1 4 7 10 13 16 19 22 25 28 31 34 37 40 43 46 49 52 55 58 61 A distinção Multicultural/ Multiculturalismo Pode ser útil fazer aqui uma distinção entre o “multicultural” e', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2019, 'Economia', NULL, 'Q8 Item 1 (TPS 2019): No que se refere aos aspectos linguísticos e semânticos do texto, julgue (C ou E) os itens a seguir. | Nas linhas 14 e 15 em “‘Multicultural’, entretanto, é, por definição, plural”, a conjunção “entretanto” apresenta a ideia de plural para o multicultural, opondo-se à de singular para o multiculturalismo. Assim, pode ser substituída por conquanto, mantendo-se o sentido e a correção gramatical do texto.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2019, 'Economia', NULL, 'Q8 Item 2 (TPS 2019): No que se refere aos aspectos linguísticos e semânticos do texto, julgue (C ou E) os itens a seguir. | Dados os sentidos do texto, é correto afirmar que os sujeitos elípticos das formas verbais “Descreve” (linha 3) e “Refere-se” (linha 9) têm referentes distintos.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2019, 'Economia', NULL, 'Q8 Item 3 (TPS 2019): No que se refere aos aspectos linguísticos e semânticos do texto, julgue (C ou E) os itens a seguir. | Em “O multiculturalismo corporativo (público ou privado) busca ‘administrar’ as diferenças culturais da minoria, visando aos interesses do centro.” (linhas de 60 a 63), a preposição que compõe a combinação “ao” poderia ser suprimida, mantendo-se a correção gramatical e as principais informações do texto, tendo em vista a variação, no português do Brasil, da transitividade do verbo visar com a acepção ter em vista, ter como fim ou objetivo.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2019, 'Economia', NULL, 'Q8 Item 4 (TPS 2019): No que se refere aos aspectos linguísticos e semânticos do texto, julgue (C ou E) os itens a seguir. | Em “É usualmente utilizado no singular, significando a filosofia específica ou a doutrina que sustenta as estratégias multiculturais.” (linhas de 11 a 14), a palavra “que” exerce a mesma função sintática que os termos “distintas sociedades multiculturais” e “‘multiculturalismos’ bastante diversos” em “Assim como há distintas sociedades multiculturais, assim também há ‘multiculturalismos’ bastante diversos.” (linhas de 42 a 44) Espaço livre QUESTÃO 9 Considerando os aspectos linguísticos e estilísticos do texto, julgue (C ou E) os itens a seguir. 1 Stuart Hall, utilizando-se da metalinguagem, conceitua os termos “multicultural” e “multiculturalismo”, além de explicar possível sentido no emprego do sufixo ismo, por meio do recurso da citação.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2019, 'Economia', NULL, 'Q10 Item 1 (TPS 2019): 1 4 7 10 13 16 19 22 23 O senhor saiba: eu toda a minha vida pensei por mim, forro, sou nascido diferente. Eu sou é eu mesmo. Diverjo de todo o mundo... Eu quase que nada não sei. Mas desconfio de muita coisa. O senhor concedendo, eu digo: para pensar longe, sou cão mestre o senhor solte em minha frente uma ideia ligeira, e eu rastreio essa por fundo de todos os matos, amém![...] A gente vive repetido, o repetido, e, escorregável, num mim minuto, já está empurrado noutro galho. Acertasse eu com  | No primeiro excerto, o narrador revela-se “forro” (linha 2) e desconfiado de tudo e de todos, perplexo diante de novas ideias e pensamentos.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2019, 'Economia', NULL, 'Q10 Item 2 (TPS 2019): 1 4 7 10 13 16 19 22 23 O senhor saiba: eu toda a minha vida pensei por mim, forro, sou nascido diferente. Eu sou é eu mesmo. Diverjo de todo o mundo... Eu quase que nada não sei. Mas desconfio de muita coisa. O senhor concedendo, eu digo: para pensar longe, sou cão mestre o senhor solte em minha frente uma ideia ligeira, e eu rastreio essa por fundo de todos os matos, amém![...] A gente vive repetido, o repetido, e, escorregável, num mim minuto, já está empurrado noutro galho. Acertasse eu com  | No segundo excerto, o narrador mostra-se confuso e contraditório, oscilando entre certeza e incerteza, conhecimento e assombro, realidade e imaginação.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2019, 'Economia', NULL, 'Q10 Item 3 (TPS 2019): 1 4 7 10 13 16 19 22 23 O senhor saiba: eu toda a minha vida pensei por mim, forro, sou nascido diferente. Eu sou é eu mesmo. Diverjo de todo o mundo... Eu quase que nada não sei. Mas desconfio de muita coisa. O senhor concedendo, eu digo: para pensar longe, sou cão mestre o senhor solte em minha frente uma ideia ligeira, e eu rastreio essa por fundo de todos os matos, amém![...] A gente vive repetido, o repetido, e, escorregável, num mim minuto, já está empurrado noutro galho. Acertasse eu com  | O sentido do adjetivo “furiável” (linha 19) remete a uma natureza ordenada, determinada; por conseguinte, o presente também se submete à lógica da obediência.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2019, 'Economia', NULL, 'Q11 Item 1 (TPS 2019): O Brasil possui uma extensa agenda internacional e construiu uma sólida inserção internacional que lhe facilita o relacionamento diplomático com quase todos os países do mundo. Acerca da participação brasileira na agenda internacional, julgue (C ou E) os itens a seguir. | O Acordo de Associação entre o Mercado Comum do Sul (MERCOSUL) e a União Europeia inclui três pilares: diálogo político, cooperação e livre comércio. O acordo comercial é composto por capítulos e anexos relativos a um conjunto de temas, entre os quais figuram: facilitação de comércio e cooperação aduaneira; integração regional; subsídios; e pequenas e médias empresas.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2019, 'Economia', NULL, 'Q11 Item 2 (TPS 2019): O Brasil possui uma extensa agenda internacional e construiu uma sólida inserção internacional que lhe facilita o relacionamento diplomático com quase todos os países do mundo. Acerca da participação brasileira na agenda internacional, julgue (C ou E) os itens a seguir. | Não obstante seu caráter inicial de fórum de diálogo, que rapidamente evoluiu no sentido de se transformar em um mecanismo de cooperação em áreas com potencial de gerar resultados concretos para os países-membros, o BRICS já logrou criar duas instituições: o Novo Banco de Desenvolvimento (NDB), que prioriza destinar recursos ao financiamento de projetos de infraestrutura, e o Arranjo Contingente de Reservas (ACR).', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2019, 'Economia', NULL, 'Q11 Item 3 (TPS 2019): O Brasil possui uma extensa agenda internacional e construiu uma sólida inserção internacional que lhe facilita o relacionamento diplomático com quase todos os países do mundo. Acerca da participação brasileira na agenda internacional, julgue (C ou E) os itens a seguir. | Criado no final dos anos de 1990 com o objetivo de promover o diálogo político e a cooperação entre os países-membros, o Fórum de Cooperação América Latina-Ásia do Leste (FOCALAL) transformou-se em importantes arranjos regionais de liberalização comercial, entre os quais sobressaem a Aliança do Pacífico e a parceria estratégica CELAC-ASEAN.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2019, 'Economia', NULL, 'Q11 Item 4 (TPS 2019): O Brasil possui uma extensa agenda internacional e construiu uma sólida inserção internacional que lhe facilita o relacionamento diplomático com quase todos os países do mundo. Acerca da participação brasileira na agenda internacional, julgue (C ou E) os itens a seguir. | O Brasil integra a Agência para a Proscrição das Armas Nucleares na América Latina e no Caribe, responsável por aplicar o Tratado de Tlatelolco nos territórios dos países-membros e nos mares adjacentes, os quais também são considerados, nos termos do tratado e de seus respectivos protocolos adicionais, livres de armas nucleares.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2019, 'Economia', NULL, 'Q12 Item 1 (TPS 2019): As relações diplomáticas entre Brasil e Rússia foram estabelecidas em 1828, culminando em diversos acordos bilaterais ao longo dos anos. Em 2002, as relações entre os dois países foram alçadas ao patamar de parceria estratégica. A esse respeito, julgue (C ou E) os itens a seguir. | Os anos de 1917 e 1947 foram marcantes nas relações políticas entre Rússia e Brasil, pois ambos significaram o rompimento temporário das relações políticas e diplomáticas.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
